new:
ui.horizontal(|ui| {
    ui.label("Arguments");
    ui.text_edit_singleline(&mut self.provider_args);
});
let previous_confinement_requirement = self.confinement_requirement;
ui.horizontal(|ui| {
    ui.label("Process confinement");
    egui::ComboBox::from_id_salt("ai_studio_process_confinement")
        .selected_text(self.confinement_requirement.label())
        .show_ui(ui, |ui| {
            for requirement in [
                AgentConfinementRequirement::AllowApplicationPolicyOnly,
                AgentConfinementRequirement::RequireProviderOrOsConfinement,
            ] {
                ui.selectable_value(
                    &mut self.confinement_requirement,
                    requirement,
                    requirement.label(),
                );
            }
        });
});
if previous_confinement_requirement != self.confinement_requirement {
    self.save_preferences();
}
let confinement_status = self
    .active_run_id
    .as_deref()
    .and_then(|run_id| self.host.run(run_id).ok())
    .and_then(|run| run.confinement_profile.as_ref())
    .map(|profile| profile.summary())
    .unwrap_or_else(|| {
        "Application policy only (generic process runtime); provider/OS confinement has not been established."
            .to_owned()
    });
ui.group(|ui| {
    ui.strong("Confinement status");
    ui.label(confinement_status);
    ui.small(
        "GameEngine application permissions remain authoritative. A first-class adapter is not treated as sandboxed unless its launch path reports enforceable provider/OS confinement.",
    );
    if self.confinement_requirement.requires_enforced_confinement() {
        ui.small(
            "Fail-closed policy: Go will not start through the generic process runtime unless a provider/OS confinement adapter can satisfy this requirement.",
        );
    }
});
ui.small(
    "The write-capable Go path launches an external AgentRuntime directly without a shell and injects the immutable proposal plus ephemeral Editor MCP connection. The local question backend above is a separate ModelBackend; a native write-capable tool loop is not enabled by this slice.",
);
